1	// Builds design/atlas.html: a 1024x1024 news atlas of Tuesday 24 November 2026.
2	// Deterministic: no randomness, no network. Map data: Natural Earth via world-atlas (data/).
3	// CHECK=1 node design/build.mjs adds a layout checker to the page (collisions, overflow); render.sh never sets it.
4	import { readFileSync, writeFileSync } from 'node:fs';
5	
6	const here = new URL('./', import.meta.url);
7	const topo = JSON.parse(readFileSync(new URL('data/countries-110m.json', here)));
8	
9	// ---- projection (Miller, cropped) -------------------------------------------------------
10	const W = 1024, LON0 = -135, LAT_TOP = 70, LAT_BOT = -44, K = W / 300;
11	const MAP_Y = 104;
12	const miller = (lat) => 1.25 * Math.log(Math.tan(Math.PI / 4 + 0.4 * lat * Math.PI / 180)) * 180 / Math.PI;
13	const MAP_H = Math.round((miller(LAT_TOP) - miller(LAT_BOT)) * K);
14	const px = (lon, lat) => [(lon - LON0) * K, (miller(LAT_TOP) - miller(lat)) * K];
15	
16	// ---- topojson decode ----------------------------------------------------------------------
17	const [sx, sy] = topo.transform.scale, [tx, ty] = topo.transform.translate;
18	const arcs = topo.arcs.map((a) => {
19	  let x = 0, y = 0;
20	  return a.map(([dx, dy]) => { x += dx; y += dy; return [x * sx + tx, y * sy + ty]; });
21	});
22	const ring = (idx) => {
23	  const pts = [];
24	  for (const i of idx) {
25	    const a = i < 0 ? arcs[~i].slice().reverse() : arcs[i];
26	    pts.push(...(pts.length ? a.slice(1) : a));
27	  }
28	  return pts;
29	};
30	const ringPath = (pts) => {
31	  let d = '';
32	  pts.forEach(([lo, la], i) => {
33	    const [x, y] = px(lo, Math.max(la, -80));
34	    d += (i ? 'L' : 'M') + x.toFixed(1) + ' ' + y.toFixed(1);
35	  });
36	  return d + 'Z';
37	};
38	const geomPath = (g) => {
39	  const polys = g.type === 'Polygon' ? [g.arcs] : g.type === 'MultiPolygon' ? g.arcs : [];
40	  return polys.map((p) => p.map((r) => ringPath(ring(r))).join('')).join('');
41	};
