244	const out=[];const hit=(a,b,p=0)=>a.x<b.x+b.w+p&&b.x<a.x+a.w+p&&a.y<b.y+b.h+p&&b.y<a.y+a.h+p;
245	const cards=G.cards.map(c=>({n:c.n,x:c.x,y:c.y,w:CW,h:CH}));
