247	const labs=[...document.querySelectorAll('.cl')].map(t=>{const b=t.getBBox();return{n:t.textContent,x:b.x,y:b.y,w:b.width,h:b.height}});
248	cards.forEach((a,i)=>{if(a.x<IN||a.y<IN||a.x+CW>MW-IN||a.y+CH>MH-IN)out.push('card '+a.n+' outside inset');
249	  cards.slice(i+1).forEach(b=>hit(a,b,6)&&out.push('cards '+a.n+'/'+b.n));
250	  pins.forEach(p=>hit(a,p,2)&&out.push('card '+a.n+' covers pin '+p.n));
251	  labs.forEach(l=>hit(a,l,2)&&out.push('card '+a.n+' covers label '+l.n));});
