260	  G.leaders.slice(i+1).forEach(([a1,b1,a2,b2,m])=>{const d=(x2-x1)*(b2-b1)-(y2-y1)*(a2-a1);if(!d)return;
261	    const t=((a1-x1)*(b2-b1)-(b1-y1)*(a2-a1))/d,u=((a1-x1)*(y2-y1)-(b1-y1)*(x2-x1))/d;t>0&&t<1&&u>0&&u<1&&out.push('leaders '+n+'/'+m+' cross')});});
262	document.querySelectorAll('.card').forEach(c=>{c.scrollHeight>c.clientHeight+1&&out.push('card '+c.dataset.n+' overflows by '+(c.scrollHeight-c.clientHeight));
263	  const h=c.querySelector('.hd');h.offsetHeight>2*parseFloat(getComputedStyle(h).lineHeight)+1&&out.push('card '+c.dataset.n+' head >2 lines');});
264	document.querySelectorAll('.dk,.d2,.pc,.pl2').forEach(d=>d.scrollWidth>d.clientWidth+1&&out.push('one-liner wraps/clips: '+d.textContent));
265	document.querySelectorAll('.h2').forEach(d=>d.offsetHeight>2*parseFloat(getComputedStyle(d).lineHeight)+1&&out.push('list head >2 lines: '+d.textContent));
266	const cols=document.querySelector('.cols');cols.scrollHeight>cols.clientHeight+1&&out.push('list overflows by '+(cols.scrollHeight-cols.clientHeight));
267	const tabs=[...document.querySelectorAll('.tab')].map(t=>t.getBoundingClientRect());
268	out.push('tab tops '+tabs.map(t=>Math.round(t.top)).join(','),'tab widths '+[...new Set(tabs.map(t=>Math.round(t.width)))].join(','),'list slack '+Math.round(cols.getBoundingClientRect().bottom-Math.max(...[...document.querySelectorAll('.it,.src')].map(e=>e.getBoundingClientRect().bottom))));
269	let min=99;document.querySelectorAll('body *').forEach(e=>{if([...e.childNodes].some(n=>n.nodeType===3&&n.textContent.trim()))min=Math.min(min,parseFloat(getComputedStyle(e).fontSize))});
270	document.querySelectorAll('text').forEach(e=>min=Math.min(min,parseFloat(getComputedStyle(e).fontSize)));out.push('min font '+min);
271	document.title=JSON.stringify(out);
272	}catch(e){document.title=JSON.stringify(['checker error: '+e.message])}</script>`;
