#!/usr/bin/env python3
"""Scratch analysis (not part of the repo): gate-equivalent stroke stats at 300px,
plus an overlay PNG showing where short (3-4px) and long (>=5px) dark runs come from."""
import sys, os, struct, zlib, subprocess
sys.path.insert(0, os.path.expanduser('~/workspace/news-1124/audit'))
import measure as M

def write_png(path, w, h, rgb_rows):
    raw = b''.join(b'\x00' + bytes(r) for r in rgb_rows)
    def chunk(t, d): return struct.pack('>I', len(d)) + t + d + struct.pack('>I', zlib.crc32(t + d) & 0xffffffff)
    open(path, 'wb').write(b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', w, h, 8, 2, 0, 0, 0)) + chunk(b'IDAT', zlib.compress(raw, 6)) + chunk(b'IEND', b''))

def analyse(png, label='x', overlay=True, zones=None):
    d300 = f'/tmp/atlas3/{label}-300.png'
    subprocess.run(['sips', '-z', '300', '300', png, '--out', d300], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    w, h, mask = M.ink_mask(d300)
    good = bad = 0
    lens = []
    marks = [[0]*w for _ in range(h)]
    zone_stats = {}
    for x in range(w):
        run = 0
        for y in range(h + 1):
            dark = y < h and mask[y][x] < 128
            if dark: run += 1
            else:
                if 3 <= run <= 26:
                    lens.append(run)
                    kind = 2 if run >= 5 else 1
                    for yy in range(y - run, y): marks[yy][x] = kind
                    if zones:
                        for name, (x0, y0, x1, y1) in zones.items():
