// Builds design/atlas.html: a 1024x1024 news atlas of Tuesday 24 November 2026.
// Deterministic: no randomness, no network. Map data: Natural Earth via world-atlas (data/).
// CHECK=1 node design/build.mjs adds a layout checker to the page (collisions, inset, overflow); render.sh never sets it.
//
// Type scale (px at 1024, nothing else is used): 56 masthead / 24 section tabs / 20 lead headline /
// 17 listed headline, continent labels, number badges and strip title / 15 kickers, legend and sources.
import { readFileSync, writeFileSync } from 'node:fs';

const here = new URL('./', import.meta.url);
const topo = JSON.parse(readFileSync(new URL('data/countries-110m.json', here)));

// ---- page bands ------------------------------------------------------------------------------
const W = 1024, HEAD_H = 80, STRIP_H = 26, FOOT_H = 24;

// ---- projection (Miller, cropped) -------------------------------------------------------
const LON0 = -135, LAT_TOP = 70, LAT_BOT = -44, K = W / 300;
const miller = (lat) => 1.25 * Math.log(Math.tan(Math.PI / 4 + 0.4 * lat * Math.PI / 180)) * 180 / Math.PI;
const MAP_Y = HEAD_H;
const MAP_H = Math.round((miller(LAT_TOP) - miller(LAT_BOT)) * K);
const px = (lon, lat) => [(lon - LON0) * K, (miller(LAT_TOP) - miller(lat)) * K];
const STRIP_Y = MAP_Y + MAP_H, LIST_Y = STRIP_Y + STRIP_H + 10, FOOT_Y = W - FOOT_H;

// ---- topojson decode ----------------------------------------------------------------------
const [sx, sy] = topo.transform.scale, [tx, ty] = topo.transform.translate;
const arcs = topo.arcs.map((a) => {
  let x = 0, y = 0;
  return a.map(([dx, dy]) => { x += dx; y += dy; return [x * sx + tx, y * sy + ty]; });
});
const ring = (idx) => {
  const pts = [];
  for (const i of idx) {
    const a = i < 0 ? arcs[~i].slice().reverse() : arcs[i];
    pts.push(...(pts.length ? a.slice(1) : a));
  }
  return pts;
};
const ringPath = (pts) => {
  let d = '';
  pts.forEach(([lo, la], i) => {
    const [x, y] = px(lo, Math.max(la, -80));
    d += (i ? 'L' : 'M') + x.toFixed(1) + ' ' + y.toFixed(1);
  });
  return d + 'Z';
};
const geomPath = (g) => {
  const polys = g.type === 'Polygon' ? [g.arcs] : g.type === 'MultiPolygon' ? g.arcs : [];
  return polys.map((p) => p.map((r) => ringPath(ring(r))).join('')).join('');
};

let land = '';
for (const g of topo.objects.countries.geometries) {
  if (g.properties.name !== 'Antarctica') land += geomPath(g);
}

// ---- stories ----------------------------------------------------------------------------------
// Lead stories: a card on the map, a red pin at loc, and a leader from the card edge to the pin.
// card:[x, y, w] in map coords (default w CARD_W). from:[side, offset]: where the leader leaves the card,
// l/r edge at y offset from the card top, t/b edge at x offset from the card left.
const CARD_W = 200, INSET = 12, PIN_R = 13;
const LEAD = [
  { n: 1, loc: [35.14, 47.84], place: 'Zaporizhzhia, Ukraine',
    hd: 'Russian strike kills 2, injures 44', card: [606, 12], from: ['l', 70] },
  { n: 2, loc: [34.45, 31.5], place: 'Gaza',
    hd: 'Israeli strike kills Hamas official Naim Abu Nahl', card: [356, 142, 190], from: ['r', 36] },
  { n: 3, loc: [46.68, 24.71], place: 'Riyadh, Saudi Arabia',
    hd: 'Houthi drone hits tower, injuring 11', card: [590, 270], from: ['t', 40] },
  { n: 4, loc: [56.3, 26.5], place: 'Strait of Hormuz',
    hd: 'Oil traffic down 40% as tanker attacks rise', card: [630, 96], from: ['b', 24] },
  { n: 5, loc: [-121.96, 37.35], place: 'Silicon Valley, US',
    hd: 'Huang back as Nvidia CEO; US blacklists Megaspeed', card: [12, 12], from: ['b', 32] },
  { n: 6, loc: [44.0, 36.19], place: 'Iraqi Kurdistan',
    hd: 'Baghdad orders takeover of oilfields, crossings', card: [812, 12], from: ['l', 60] },
  { n: 7, loc: [-0.12, 51.5], place: 'United Kingdom',
    hd: 'Record 5,258 heat deaths this summer', card: [232, 112], from: ['r', 12] },
  { n: 8, loc: [90.4, 23.8], place: 'Dhaka, Bangladesh',
    hd: 'Hasina plans return from exile on 16 Dec', card: [812, 120], from: ['l', 70] },
  { n: 9, loc: [101.7, 3.14], place: 'Kuala Lumpur, Malaysia',
    hd: 'Thousands of Rohingya to be sent to Myanmar', card: [832, 236, 180], from: ['l', 44] },
  { n: 10, loc: [-17.45, 14.7], place: 'Dakar, Senegal',
    hd: 'Senegal reinstated as AFCON 2025 champions', card: [226, 270], from: ['t', 170] },
  { n: 11, loc: [-75.5, 10.4], place: 'Cartagena, Colombia',
    hd: 'Gunmen hold 25 hostages in a supermarket', card: [12, 352], from: ['t', 180] },
  { n: 12, loc: [-73.95, 40.65], place: 'US federal court',
    hd: 'Huawei guilty of trade-secrets conspiracy, fraud', card: [222, 12], from: ['b', 8] },
];

// The list: a 4x2 grid of sections, row 1 then row 2, numbered 13-34 in reading order.
// Every story with one place gets a black pin at loc (off:[dx, dy] moves a crowded pin and draws a tick);
// sport and worldwide stories have no single place and no pin.
const SECTIONS = [
  { tab: 'The Americas', items: [
    { loc: [-77.04, 38.9], off: [-6, 26], hd: 'Trump urges faster federal executions' },
    { loc: [-107.4, 24.8], hd: 'Mexico to try ‘El Chapo Isidro’ on drug and weapons charges' },
    { loc: [-82.36, 23.1], hd: 'WHO chief visits Cuba as health care falters' },
    { loc: [-72.34, 18.54], hd: 'Bukele details troop deaths in Haiti mission' },
  ] },
  { tab: 'Europe', items: [
    { loc: [37.6, 55.75], hd: 'Putin vows to retaliate for oil-plant strikes' },
    { loc: [30.52, 39.78], hd: 'Turkish military helicopter crash kills five' },
    { loc: [10.75, 59.9], hd: 'Cameroon separatist denies war crimes in Norway' },
  ] },
  { tab: 'Africa', items: [
    { loc: [30.25, 1.56], hd: 'Rebels halt advance on Bunia, DR Congo' },
    { loc: [13.16, 11.85], hd: 'School enrolment nearly doubles in Borno' },
    { loc: [28.05, -26.2], hd: 'Zimbabwean convicted of trying to fight for Russia' },
  ] },
  { tab: 'Asia', items: [
    { loc: [105.83, 21.0], hd: 'Restaurant blast in Hanoi kills at least six' },
    { loc: [126.98, 37.57], hd: 'Air-raid alert as Russian jets near South Korea' },
    { loc: [113.26, 23.13], off: [12, 22], hd: 'China Southern unit to buy 50 Boeing 737s' },
    { loc: [121.47, 31.23], hd: 'China probes Shanghai party chief Chen Jining' },
  ] },
  { tab: 'Middle East', items: [
    { loc: [34.45, 31.5], off: [-30, 6], hd: 'Strikes kill 7 in Gaza as meningitis spreads' },
    { loc: [55.95, 25.8], off: [0, 32], hd: 'Bus crash kills 13 in Ras Al Khaimah, UAE' },
    { loc: [42.95, 14.8], hd: 'Saudi-led coalition orders Hodeidah port cleared' },
  ] },
  { tab: 'Oceania', items: [
    { loc: [149.13, -35.28], hd: 'Australia bill: tech fines up to 5% of revenue' },
  ] },
  { tab: 'Sport', items: [
    { hd: 'Arsenal 1-1 Dortmund; Real Madrid rout PSV 5-1' },
    { hd: 'India’s Sooryavanshi, 15, hits 204 off 53 balls' },
  ] },
  { tab: 'Worldwide', items: [
    { hd: 'WFP: wars put food aid for 7.3 million at risk' },
    { hd: 'Five women killed every hour by partner or kin' },
  ] },
];
let next = LEAD.length + 1;
for (const sec of SECTIONS) for (const it of sec.items) it.n = next++;
const LAST = next - 1;
const LISTED = SECTIONS.flatMap((s) => s.items);
const PINNED_LAST = Math.max(...LISTED.filter((i) => i.loc).map((i) => i.n));

// Continent names, set in open water (map coords, text centre).
const REGIONS = [
  ['THE AMERICAS', 104, 252], ['EUROPE', 452, 30], ['AFRICA', 452, 330],
  ['MIDDLE EAST', 700, 238], ['ASIA', 960, 160], ['OCEANIA', 900, 434],
];

// ---- render ----------------------------------------------------------------------------------
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;');
const badge = (n, cls) => `<span class="bd ${cls}">${n}</span>`;
const f1 = (v) => +v.toFixed(1);

const graticule = [];
for (let lon = -120; lon <= 160; lon += 30) { const [x] = px(lon, 0); graticule.push(`M${x.toFixed(1)} 0V${MAP_H}`); }
for (const lat of [-30, 0, 30, 60]) { const [, y] = px(0, lat); graticule.push(`M0 ${y.toFixed(1)}H${W}`); }
const [, eqY] = px(0, 0);

const cardBox = (s) => ({ x: s.card[0], y: s.card[1], w: s.card[2] ?? CARD_W });
const anchor = (s) => {
  const { x, y, w } = cardBox(s), [side, o] = s.from;
  return side === 'l' ? [x, y + o] : side === 'r' ? [x + w, y + o] : side === 't' ? [x + o, y] : [x + o, y + s.h];
};

// Geometry, kept for the checker: pins {n, x, y} at badge centres, leaders [x1, y1, x2, y2, n].
const geo = { pins: [], leaders: [] };
// Draw order: leaders and ticks, then black pins, then red pins, so a lead pin is never covered.
let leaders = '', ticks = '', pinsK = '', pinsR = '';
const pin = (x, y, n, cls) => `<g transform="translate(${x} ${y})"><circle class="${cls}" r="${PIN_R}"/><text class="pn" y="6">${n}</text></g>`;
for (const s of LEAD) {
  const [x, y] = px(...s.loc).map(f1);
  pinsR += pin(x, y, s.n, 'pr');
  geo.pins.push({ n: s.n, x, y });
}
for (const s of LISTED) {
  if (!s.loc) continue;
  const [x, y] = px(...s.loc).map(f1);
  const [dx, dy] = s.off ?? [0, 0];
  if (dx || dy) ticks += `<path class="tk" d="M${x} ${y}l${dx} ${dy}"/><circle class="dot" cx="${x}" cy="${y}" r="2.5"/>`;
  pinsK += pin(f1(x + dx), f1(y + dy), s.n, 'pk');
  geo.pins.push({ n: s.n, x: f1(x + dx), y: f1(y + dy) });
}
const regionLabels = REGIONS.map(([t, x, y]) => `<text class="cl" x="${x}" y="${y}">${t}</text>`).join('');

const cards = LEAD.map((s) => {
  const { x, y, w } = cardBox(s);
  return `
<div class="card" data-n="${s.n}" style="left:${x}px;top:${y}px;width:${w}px">
  <div class="kick">${badge(s.n, 'r')}<span class="pc">${esc(s.place)}</span></div>
  <div class="hd">${esc(s.hd)}</div>
</div>`;
}).join('');

const cells = SECTIONS.map((sec) => `<div class="cell"><div class="tab">${sec.tab}</div>${sec.items.map((s) => `
<div class="it">${badge(s.n, 'k')}<div class="h2">${esc(s.hd)}</div></div>`).join('')}</div>`).join('');

// Layout checker (CHECK=1 only): measures the laid-out page, writes a JSON report into document.title.
const checker = !process.env.CHECK ? '' : `<script>try{
const G=${JSON.stringify(geo)},R=${PIN_R},IN=${INSET},MW=${W},MH=${MAP_H},MY=${MAP_Y};
const out=[];const hit=(a,b,p=0)=>a.x<b.x+b.w+p&&b.x<a.x+a.w+p&&a.y<b.y+b.h+p&&b.y<a.y+a.h+p;
const cards=[...document.querySelectorAll('.card')].map(c=>{const r=c.getBoundingClientRect();return{n:+c.dataset.n,x:r.left,y:r.top-MY,w:r.width,h:r.height}});
const pins=G.pins.map(p=>({n:p.n,x:p.x-R,y:p.y-R,w:2*R,h:2*R,cx:p.x,cy:p.y}));
const labs=[...document.querySelectorAll('.cl')].map(t=>{const b=t.getBBox();return{n:t.textContent,x:b.x,y:b.y,w:b.width,h:b.height}});
cards.forEach((a,i)=>{const m=[a.x,a.y,MW-a.x-a.w,MH-a.y-a.h].map(v=>Math.round(v));if(Math.min(...m)<IN)out.push('card '+a.n+' inset l,t,r,b='+m.join(','));
  cards.slice(i+1).forEach(b=>hit(a,b,6)&&out.push('cards '+a.n+'/'+b.n));
  pins.forEach(p=>hit(a,p,2)&&out.push('card '+a.n+' covers pin '+p.n));
  labs.forEach(l=>hit(a,l,4)&&out.push('card '+a.n+' covers label '+l.n));});
labs.forEach(l=>{pins.forEach(p=>hit(l,p,2)&&out.push('label '+l.n+' on pin '+p.n));if(l.x<IN||l.x+l.w>MW-IN||l.y<IN||l.y+l.h>MH-IN)out.push('label '+l.n+' near frame')});
pins.forEach((a,i)=>pins.slice(i+1).forEach(b=>Math.hypot(a.cx-b.cx,a.cy-b.cy)<2*R+3&&out.push('pins '+a.n+'/'+b.n)));
const near=(x1,y1,x2,y2,px,py)=>{const dx=x2-x1,dy=y2-y1,t=Math.max(0,Math.min(1,((px-x1)*dx+(py-y1)*dy)/(dx*dx+dy*dy)));return Math.hypot(x1+t*dx-px,y1+t*dy-py)};
const L=[...document.querySelectorAll('.ld')].map(l=>[...l.getAttribute('d').matchAll(/[-\\d.]+/g)].map(Number).concat(+l.dataset.n));
L.forEach(([x1,y1,x2,y2,n],i)=>{
  for(let k=1;k<60;k++){const x=x1+(x2-x1)*k/60,y=y1+(y2-y1)*k/60;
    cards.forEach(c=>c.n!==n&&x>c.x-3&&x<c.x+c.w+3&&y>c.y-3&&y<c.y+c.h+3&&out.push('leader '+n+' crosses card '+c.n));
    labs.forEach(l=>x>l.x-2&&x<l.x+l.w+2&&y>l.y-2&&y<l.y+l.h+2&&out.push('leader '+n+' crosses label '+l.n));}
  pins.forEach(p=>p.n!==n&&near(x1,y1,x2,y2,p.cx,p.cy)<R+3&&out.push('leader '+n+' grazes pin '+p.n));
  L.slice(i+1).forEach(([a1,b1,a2,b2,m])=>{const d=(x2-x1)*(b2-b1)-(y2-y1)*(a2-a1);if(!d)return;
    const t=((a1-x1)*(b2-b1)-(b1-y1)*(a2-a1))/d,u=((a1-x1)*(y2-y1)-(b1-y1)*(x2-x1))/d;t>0&&t<1&&u>0&&u<1&&out.push('leaders '+n+'/'+m+' cross')});});
document.querySelectorAll('.card .hd').forEach(h=>out.push('lead '+h.parentNode.dataset.n+' lines '+Math.round(h.offsetHeight/parseFloat(getComputedStyle(h).lineHeight))+' h '+h.parentNode.offsetHeight));
document.querySelectorAll('.pc').forEach(d=>d.scrollWidth>d.clientWidth+1&&out.push('kicker clips: '+d.textContent));
document.querySelectorAll('.h2').forEach(d=>{const n=Math.round(d.offsetHeight/parseFloat(getComputedStyle(d).lineHeight));n>2&&out.push('list head '+n+' lines: '+d.textContent)});
const cols=document.querySelector('.cols');out.push('list slack '+Math.round(cols.getBoundingClientRect().bottom-Math.max(...[...document.querySelectorAll('.it')].map(e=>e.getBoundingClientRect().bottom))));
const tabs=[...document.querySelectorAll('.tab')].map(t=>t.getBoundingClientRect());
out.push('tab tops '+tabs.map(t=>Math.round(t.top)).join(','),'tab widths '+[...new Set(tabs.map(t=>Math.round(t.width)))].join(','));
const sz=new Set();document.querySelectorAll('body *').forEach(e=>{if([...e.childNodes].some(n=>n.nodeType===3&&n.textContent.trim()))sz.add(parseFloat(getComputedStyle(e).fontSize))});
document.querySelectorAll('text').forEach(e=>sz.add(parseFloat(getComputedStyle(e).fontSize)));out.push('font sizes '+[...sz].sort((a,b)=>a-b).join(','));
document.title=JSON.stringify(out);
}catch(e){document.title=JSON.stringify(['checker error: '+e.message])}</script>`;

// Card heights are fixed by their headline line count; computed here so leaders can leave a card's bottom edge.
// (20px headline at 22px leading; the checker reports the real line count and card height.)
for (const s of LEAD) s.h = s.lines === 3 ? 103 : 81;
for (const s of LEAD) {
  const [x, y] = px(...s.loc).map(f1);
  const [ax, ay] = anchor(s);
  geo.leaders.push([x, y, ax, ay, s.n]);
  leaders += `<path class="ld" data-n="${s.n}" d="M${x} ${y}L${ax} ${ay}"/><circle class="ae" cx="${ax}" cy="${ay}" r="3"/>`;
}

const SANS = '"Avenir Next Condensed","Avenir Next","Helvetica Neue",sans-serif';
const TEXT = '"Avenir Next","Helvetica Neue",sans-serif';
const html = `<!doctype html><html><head><meta charset="utf-8"><title>atlas</title><style>
:root{--paper:#F4F0E6;--ink:#191C22;--mute:#3E424A;--acc:#C0391F;--sea:#D3DEE0;--land:#EAE3D2}
*{box-sizing:border-box;margin:0;padding:0}
html,body{width:1024px;height:1024px;overflow:hidden;background:var(--paper);color:var(--ink)}
body{position:relative;font-family:${SANS};-webkit-font-smoothing:antialiased}
.head{position:absolute;left:0;top:0;width:${W}px;height:${HEAD_H}px;background:var(--ink);color:var(--paper)}
h1{position:absolute;left:20px;top:7px;font:700 56px/66px Charter,"Bitstream Charter",Georgia,serif;letter-spacing:-.01em}
.strap{position:absolute;right:20px;top:23px;text-align:right;font:700 15px/17px ${SANS};letter-spacing:.07em;text-transform:uppercase}
.strap b{color:#F0A08C;font-weight:700}
.map{position:absolute;left:0;top:${MAP_Y}px;width:${W}px;height:${MAP_H}px;overflow:hidden}
.map>svg{position:absolute;left:0;top:0}
.sea{fill:var(--sea)} .land{fill:var(--land);stroke:#FBF8F1;stroke-width:.7}
.gr{fill:none;stroke:#C2CFD1;stroke-width:.6} .eq{fill:none;stroke:#A9B8BA;stroke-width:.8;stroke-dasharray:3 3}
.cl{font:700 17px ${SANS};letter-spacing:.3em;fill:#3A5560;text-anchor:middle}
.ld{fill:none;stroke:var(--acc);stroke-width:1.8} .ae{fill:var(--acc)}
.tk{fill:none;stroke:var(--ink);stroke-width:1.4} .dot{fill:var(--ink)}
.pr{fill:var(--acc);stroke:#fff;stroke-width:1.5} .pk{fill:var(--ink);stroke:#fff;stroke-width:1.5}
.pn{font:800 17px ${SANS};fill:#fff;text-anchor:middle}
.bd{display:inline-flex;align-items:center;justify-content:center;flex:none;width:${2 * PIN_R}px;height:${2 * PIN_R}px;border-radius:50%;color:#fff;font:800 17px/1 ${SANS}}
.bd.r{background:var(--acc)} .bd.k{background:var(--ink)}
.card{position:absolute;background:#fff;border:1.5px solid var(--ink)}
.kick{display:flex;align-items:center;gap:7px;height:26px;background:var(--ink);color:var(--paper);margin:-1.5px -1.5px 0;padding-right:8px}
.pc{font:700 15px/1 ${SANS};letter-spacing:.06em;text-transform:uppercase;white-space:nowrap;overflow:hidden}
.hd{font:800 20px/22px ${SANS};padding:4px 8px 6px}
.also{position:absolute;left:0;top:${STRIP_Y}px;width:${W}px;height:${STRIP_H}px;background:var(--ink);color:var(--paper);display:flex;align-items:center;justify-content:space-between;padding:0 20px}
.also .t{font:700 17px/1 ${SANS};letter-spacing:.1em;text-transform:uppercase}
.also .s{font:700 15px/1 ${SANS};letter-spacing:.05em;text-transform:uppercase}
.also .s b{color:#F0A08C;font-weight:700}
.cols{position:absolute;left:20px;right:20px;top:${LIST_Y}px;bottom:${FOOT_H + 8}px;display:grid;grid-template-columns:repeat(4,1fr);grid-template-rows:auto auto;column-gap:20px;row-gap:12px;align-content:start;overflow:hidden}
.tab{height:30px;font:800 24px/30px ${SANS};letter-spacing:.08em;text-transform:uppercase;background:var(--ink);color:var(--paper);padding:0 8px;margin-bottom:8px;white-space:nowrap}
.it{display:flex;gap:9px;margin-bottom:8px}
.h2{font:700 17px/20px ${TEXT};padding-top:3px;min-width:0}
.foot{position:absolute;left:0;top:${FOOT_Y}px;width:${W}px;height:${FOOT_H}px;background:var(--ink);color:var(--paper);font:500 15px/${FOOT_H}px ${TEXT};padding:0 20px;white-space:nowrap}
</style></head><body>
<div class="head"><h1>Tuesday 24 November 2026</h1>
<div class="strap"><b>One day on Earth</b> · ${LAST} stories<br>6 regions · sport · worldwide</div></div>
<div class="map">
<svg width="${W}" height="${MAP_H}" viewBox="0 0 ${W} ${MAP_H}">
<rect class="sea" width="${W}" height="${MAP_H}"/>
<path class="gr" d="${graticule.join('')}"/>
<path class="land" d="${land}"/>
<path class="eq" d="M0 ${eqY.toFixed(1)}H${W}"/>
${regionLabels}
${leaders}
</svg>
${cards}
<svg width="${W}" height="${MAP_H}" viewBox="0 0 ${W} ${MAP_H}" style="pointer-events:none">${ticks}${pinsK}${pinsR}</svg>
</div>
<div class="also"><span class="t">Also on Tuesday 24 November</span><span class="s"><b>Red 1–${LEAD.length}</b> lead stories · black ${LEAD.length + 1}–${PINNED_LAST} pinned · ${PINNED_LAST + 1}–${LAST} no single place, no pin</span></div>
<div class="cols">${cells}</div>
<div class="foot">Sources: Al Jazeera reports and Wikipedia’s Current events portal, 24 Nov 2026 · Figures as reported · Map: Natural Earth</div>
${checker}
</body></html>`;

writeFileSync(new URL('atlas.html', here), html);
console.log('map height', MAP_H, 'stories', LAST, 'pinned', geo.pins.length);

