// Builds design/atlas.html: a 1024x1024 news atlas of Tuesday 24 November 2026.
// Deterministic: no randomness, no network. Map data: Natural Earth via world-atlas (data/).
// CHECK=1 node design/build.mjs adds a layout checker to the page (collisions, inset, overflow); render.sh never sets it.
//
// Type scale (px at 1024, nothing else is used): 56 masthead / 24 section tabs / 20 lead headline /
// 17 listed headline, continent labels, number badges and strip title / 15 kickers, legend and sources.
import { readFileSync, writeFileSync } from 'node:fs';

const here = new URL('./', import.meta.url);
const topo = JSON.parse(readFileSync(new URL('data/countries-110m.json', here)));

// ---- page bands ------------------------------------------------------------------------------
const W = 1024, HEAD_H = 80, STRIP_H = 26, FOOT_H = 24;

// ---- projection (Miller, cropped) -------------------------------------------------------
const LON0 = -135, LAT_TOP = 70, LAT_BOT = -44, K = W / 300;
const miller = (lat) => 1.25 * Math.log(Math.tan(Math.PI / 4 + 0.4 * lat * Math.PI / 180)) * 180 / Math.PI;
const MAP_Y = HEAD_H;
const MAP_H = Math.round((miller(LAT_TOP) - miller(LAT_BOT)) * K);
const px = (lon, lat) => [(lon - LON0) * K, (miller(LAT_TOP) - miller(lat)) * K];
const STRIP_Y = MAP_Y + MAP_H, LIST_Y = STRIP_Y + STRIP_H + 10, FOOT_Y = W - FOOT_H;

// ---- topojson decode ----------------------------------------------------------------------
const [sx, sy] = topo.transform.scale, [tx, ty] = topo.transform.translate;
const arcs = topo.arcs.map((a) => {
  let x = 0, y = 0;
  return a.map(([dx, dy]) => { x += dx; y += dy; return [x * sx + tx, y * sy + ty]; });
});
const ring = (idx) => {
  const pts = [];
  for (const i of idx) {
    const a = i < 0 ? arcs[~i].slice().reverse() : arcs[i];
    pts.push(...(pts.length ? a.slice(1) : a));
  }
  return pts;
};
const ringPath = (pts) => {
  let d = '';
  pts.forEach(([lo, la], i) => {
    const [x, y] = px(lo, Math.max(la, -80));
    d += (i ? 'L' : 'M') + x.toFixed(1) + ' ' + y.toFixed(1);
  });
  return d + 'Z';
};
const geomPath = (g) => {
  const polys = g.type === 'Polygon' ? [g.arcs] : g.type === 'MultiPolygon' ? g.arcs : [];
  return polys.map((p) => p.map((r) => ringPath(ring(r))).join('')).join('');
};

let land = '';
for (const g of topo.objects.countries.geometries) {
  if (g.properties.name !== 'Antarctica') land += geomPath(g);
}

// ---- stories ----------------------------------------------------------------------------------
// Lead stories: a card on the map, a red pin at loc, and a leader from the card edge to the pin.
// card:[x, y, w] in map coords (default w CARD_W). from:[side, offset]: where the leader leaves the card,
// l/r edge at y offset from the card top, t/b edge at x offset from the card left.
const CARD_W = 200, INSET = 12, PIN_R = 13;
const LEAD = [
  { n: 1, loc: [35.14, 47.84], place: 'Zaporizhzhia, Ukraine',
    hd: 'Russian strike kills 2, injures 44', card: [606, 12], from: ['l', 70] },
  { n: 2, loc: [34.45, 31.5], place: 'Gaza',
    hd: 'Israeli strike kills Hamas official Naim Abu Nahl', card: [356, 142, 190], from: ['r', 36] },
  { n: 3, loc: [46.68, 24.71], place: 'Riyadh, Saudi Arabia',
    hd: 'Houthi drone hits tower, injuring 11', card: [590, 270], from: ['t', 40] },
  { n: 4, loc: [56.3, 26.5], place: 'Strait of Hormuz',
    hd: 'Oil traffic down 40% as tanker attacks rise', card: [630, 96], from: ['b', 24] },
  { n: 5, loc: [-121.96, 37.35], place: 'Silicon Valley, US',
    hd: 'Huang back as Nvidia CEO; US blacklists Megaspeed', card: [12, 12], from: ['b', 32] },
  { n: 6, loc: [44.0, 36.19], place: 'Iraqi Kurdistan',
    hd: 'Baghdad orders takeover of oilfields, crossings', card: [812, 12], from: ['l', 60] },
  { n: 7, loc: [-0.12, 51.5], place: 'United Kingdom',
    hd: 'Record 5,258 heat deaths this summer', card: [232, 112], from: ['r', 12] },
  { n: 8, loc: [90.4, 23.8], place: 'Dhaka, Bangladesh',
    hd: 'Hasina plans return from exile on 16 Dec', card: [812, 120], from: ['l', 70] },
  { n: 9, loc: [101.7, 3.14], place: 'Kuala Lumpur, Malaysia',
    hd: 'Thousands of Rohingya to be sent to Myanmar', card: [832, 236, 180], from: ['l', 44] },
  { n: 10, loc: [-17.45, 14.7], place: 'Dakar, Senegal',
    hd: 'Senegal reinstated as AFCON 2025 champions', card: [226, 270], from: ['t', 170] },
  { n: 11, loc: [-75.5, 10.4], place: 'Cartagena, Colombia',
    hd: 'Gunmen hold 25 hostages in a supermarket', card: [12, 352], from: ['t', 180] },
  { n: 12, loc: [-73.95, 40.65], place: 'US federal court',
    hd: 'Huawei guilty of trade-secrets conspiracy, fraud', card: [222, 12], from: ['b', 8] },
];

// The list: a 4x2 grid of sections, row 1 then row 2, numbered 13-34 in reading order.
// Every story with one place gets a black pin at loc (off:[dx, dy] moves a crowded pin and draws a tick);
// sport and worldwide stories have no single place and no pin.
const SECTIONS = [
  { tab: 'The Americas', items: [
    { loc: [-77.04, 38.9], off: [-6, 26], hd: 'Trump urges faster federal executions' },
    { loc: [-107.4, 24.8], hd: 'Mexico to try ‘El Chapo Isidro’ on drug and weapons charges' },
