// ---- render ----------------------------------------------------------------------------------
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;');
const icon = (id) => `<svg class="ic" viewBox="0 0 24 24"><use href="#i-${id}"/></svg>`;
